-- The two checklists published on 2026-10-19: When a Friendship Has Run Its
-- Course (Friendship) and Your First Month Retired (Retirement).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-19`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-a-friendship-has-run-its-course', 'When a Friendship Has Run Its Course', 'For a friendship that has quietly thinned out and may be over. It helps you tell a drift from a rift, make one clear attempt before deciding, and let the thing end without turning it into a verdict on either of you.', 'Friendship', '["Notice who has been doing the reaching — a one-sided thread is information, not an accusation.", "Ask whether this is a drift or a rift — one needs an effort and the other needs a decision.", "Make one clear invitation before you decide — vague plans let both of you off the hook.", "Stop keeping score of the silences — the tally feeds the hurt and settles nothing.", "Decide whether the ending needs saying out loud — most friendships close quietly and that is allowed.", "Let it be sad without making it a verdict — a friendship can end without either of you failing.", "Keep what it gave you, not just how it ended — good years do not stop counting because the last months were thin.", "Put the free evening toward someone current — an old friendship is easier to mourn beside a present one."]'::jsonb, 'as needed', array['Relationships', 'Loneliness']::text[], 1, '2026-10-19T16:00:00+00:00'::timestamptz),
  ('your-first-month-retired', 'Your First Month Retired', 'For the first weeks after finishing work, when the days arrive with nothing already in them. It keeps one fixed point in the day, names what the job was giving you besides money, and expects the flat stretch that follows the first excitement.', 'Retirement', '["Keep one fixed point in the day — a walk or a meal at the same hour holds a shapeless week together.", "Do not fill the calendar in week one — the quiet is worth meeting before you cover it over.", "Name what work gave you besides money — company, status, a reason to be somewhere at nine.", "Find one thing with other people in it — a class, a club, a shift; colleagues do not replace themselves.", "Pick one project with no deadline on it — something to be partway through beats something finished.", "Say the date plainly when asked what you do — “I retired in March” is an answer, not an apology.", "Book what work used to crowd out — the dentist, the eyes, the thing you kept moving.", "Expect a flat week somewhere in the middle — the dip after the first excitement is normal, not a mistake."]'::jsonb, 'weekly', array['Life Transitions', 'Habits']::text[], 1, '2026-10-19T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
